      "notes": "Batek (ISO 639-3 btq, Glottolog bate1262) is an Aslian (Austroasiatic) language documented in Peninsular Malaysia (Pahang, Kelantan, Terengganu), including the Taman Negara area (Ethnologue 18th ed. 2015). All 25 seeds are Orang Asli villages / settlements in the documented Batek area: Kuala Tahan, Kuala Tembeling, Sungai Tahan, Merapoh, Kuala Koh, Kampung Orang Asli Kuala Koh, Kampung Orang Asli Dedari, Kuala Keniam, Sungai Sat, Jeram Dedari, Teresek, Sungai Kechau, Teluk Gunung, Kuala Atok, Sungai Yong, Sungai Tabung, Semetong, Sungai Cheka, Kuala Kemiang, Kampung Aring 5 (Kelantan), Kampung Sungai Berua, Kampung Sungai Sayap, Pasir Lenggi, Kampung Pasir Linggi, Sungai Yong. Names follow Orang Asli village naming (Kampung, Kuala, Sungai). No duplicates, padding, non-place tokens, self-names, or language-name-as-seed. All seeds are real settlements in the documented Batek area."
