      "verified_at": "2026-10-20T08:07:35.976Z",
      "notes": "ISO 639-3: sza. Glottolog: seme1247. Semelai is spoken around Bera Lake (Tasik Bera/Tasek Bera), Pahang, and along the Bera, Serting, Teriang, and Muar river systems in Pahang, Negeri Sembilan, and Johor. Multiple seeds are not settlements: Tasek Bera and Tasik are lake names (Tasik Bera is Malaysia's largest freshwater lake, not a settlement), Sungai Bera/Sungai Serting/Sungai Triang are river names, Bera is a district/river/lake name, Jempol is a district name, Muar is primarily a Johor town (Semelai area is Ulu Muar), Bukit Chermingat is a hill/boundary marker. Bukit Rok and Gemuroh are duplicates/partials of Kampung Bukit Rok/Kampung Bukit Gemuroh. After removing non-settlement and duplicate seeds, approximately 15 of 26 remain, below the 25-seed floor."
