      "notes": "Aramaic is a language family with multiple modern varieties (Western Neo-Aramaic ISO 639-3 atc; Eastern Aramaic varieties have separate ISO codes). Western Neo-Aramaic is spoken only in 3 villages near Damascus, Syria: Maaloula, Jubb'adin, Bakh'a. Eastern Aramaic (Assyrian/Chaldean/Syriac) communities exist in Nineveh Plain and Kurdistan Region of Iraq (Alqosh, Tel Keppe, Batnaya, Bartella, Bakhdida/Qaraqosh, Karamlesh, Tesqopa, Ankawa, Dohuk, Zakho, Amadiya) and NE Syria (Qamishli, Al-Hasakah) and SE Turkey (Midyat). Many seeds are major cities where Aramaic is not the primary settlement language (Damascus, Homs, Diyarbakir, Urfa, Baghdad, Mosul, Erbil, Kirkuk) or are not specifically Aramaic-speaking (Sadad, Deir Atiyah, Qaryatayn, Ain al-Tinah). Only ~17 seeds confirmed as Aramaic-speaking settlements (<25 floor). Entry cannot be verified as a coherent Aramaic settlement list."
