      "notes": "ISO 639-3 aph; Glottolog athp1241. Athpahariya/Athpare is an Eastern Kiranti language spoken in Dhankuta District, eastern Nepal — specifically north of the Tamur, west of the Dhankuta khola, east of Tangkhuwa, in Dhankuta municipality and Bhirgau VDC (Wikipedia; Ebert 1997 grammar via Glottolog/STEDT). The seed list is a generic eastern-Nepal district/town list covering Terhathum, Taplejung, Panchthar, Ilam, Sankhuwasabha, Solukhumbu, Udayapur, Sunsari, Morang, Jhapa (other districts), Lalitpur and Bhaktapur (Kathmandu Valley), Birgunj and Janakpur (Terai), and Butwal/Palpa/Syangja/Gorkha/Dhading/Sindhuli/Ramechhap (central Nepal) — none of these are in Dhankuta District. The entry also shares 28 seeds with the Chintang entry (i=838), indicating a copied regional block rather than language-specific settlements. Only ~7 seeds (Dhankuta, Hile, Myanglung, Bhirgaun, Tamur, Tangkhuwa, Aatharai) are in/near Dhankuta, below the 25 floor -> unverified."
