      "notes": "Sora/Savara (ISO 639-3: srb, Glottolog: sora1254) is a South Munda language spoken mainly in Ganjam, Gajapati and Rayagada districts of Odisha, with communities in Koraput, Phulbani/Kandhamal and northern Andhra Pradesh (Srikakulam, Vizianagaram). Primary sources confirm: Odisha gov Gajapati district portal lists blocks Gosani, Gumma, Kasinagar, Mohana, Nuagada, R.Udayagiri, Rayagada (all Sora-area blocks); Gajapati district is 34.49% Sora-speaking (2011 Census); Rayagada district towns/villages include Bhaliapadar, Bissam Cuttack, Chatikona, Gudari, Gunupur, Kujendri, Muniguda, Padmapur, Rayagada, Sirijholi; Serango is a Sora village in Gumma tahasil, Gajapati; Gunupur is a Rayagada municipality; Wikipedia Sora people notes interior GPs Rejingtal, Sagada, Puttasingi and concentrations around Gunupur/Gumma/Serango/Puttasingi. All 26 retained seeds are real settlements in the documented Sora area. Removed 7 district/region names that are not settlements or are outside the core Sora area: Gajapati, Koraput, Phulbani, Bargarh, Kandhamal, Nabarangpur, Malkangiri. Note: 'RUdayagiri' is the R. Udayagiri block/town (capitalization irregular but refers to a real place). 26 valid seeds >= 25 COMPLETE threshold."
