      "notes": "Lao Phutai = Phu Thai, a Southwestern Tai (Kra-Dai) language. ISO 639-3: pht; Glottolog: phut1244 (Glottolog 5.3). Spoken in Lao PDR (Khammouane and Savannakhet Provinces), Thailand (Nakhon Phanom, Mukdahan, Kalasin, Sakon Nakhon), and Vietnam. Ethnologue lists it as a stable indigenous language. The Waritchaphum dialect is documented (Gedney & Hudak 1997). Ban Khok Kong is a confirmed Phu Thai village (Phu Thai Khok Kong Cultural Village, Nakhon Phanom). Ban Phak Kha Nya is a confirmed Phu Thai village in Atsaphone District, Savannakhet Province. Konglor (Kong Lor) is a village in Khammouane Province, Laos. Savannakhet is the provincial capital. Seeds use the 'Ban' (village) prefix consistent with Lao/Thai toponymy. Integrity checks pass: no duplicates, no synthetic/stem padding, no template padding, no non-place tokens, no self-references."
