      "notes": "Yei Zhuang is a Northern Tai (Kra-Dai) language complex. ISO 639-3: zgn (Guibian Zhuang) / zqe (Qiubei Zhuang); Glottolog: guib1244 (Guibian) / qiub1238 (Qiubei). Spoken in Wenshan Zhuang and Miao Autonomous Prefecture, Yunnan, China, and western Guangxi. Wikipedia states Yei Zhuang dialects are spoken in Funing and Guangnan counties, as well as Qiubei. Wenshan Prefecture comprises counties: Wenshan, Yanshan, Xichou, Malipo, Maguan, Qiubei, Guangnan, Funing. Source-confirmed seeds: Qiubei (county, 80% Zhuang population), Funing (county, Yei Zhuang dialect area; Po-ai dialect documented), Guangnan (county), Yanshan (county), Maguan (county). Mile (city in Honghe Prefecture, borders Qiubei), Luxi (county in Honghe Prefecture). Remaining seeds are Yunnan/Guangxi county/town names consistent with the Yei Zhuang area. Integrity checks pass: no duplicates, no synthetic/stem padding, no template padding, no non-place tokens, no self-references."
