      "notes": "Braj Bhasha (ISO 639-3: bra, Glottolog: braj1242) is spoken in the Braj region of western Uttar Pradesh (centred on Mathura/Agra; also Aligarh, Hathras, Firozabad, Mainpuri, Etah, Bulandshahr incl. Khurja/Dibai, parts of Bareilly/Farrukhabad/Badaun), eastern Rajasthan (Bharatpur, Deeg, Karauli, Dholpur), Haryana (Palwal, Faridabad, eastern Gurugram), and Madhya Pradesh (Morena, Gwalior). Wikipedia's Braj Bhasha geographical distribution explicitly names Mathura, Hathras, Agra, Aligarh, Firozabad, Mainpuri, Etah, Budaun/Badaun, Bareilly, Bulandshahr, Bharatpur, Deeg, Karauli, Dholpur, Palwal, Faridabad, Gurugram, Vrindavan, Kosi Kalan, Chhata, Baldeo, Kaman, Surir, Bhidauni, Gwalior, Morena. All 30 seeds are real towns in the documented Braj region. No duplicates, no language-name-as-seed, no non-place tokens."
