      "verified_at": "2026-10-20T08:07:35.977Z",
      "notes": "Chongqing Mandarin is the Cheng-Yu (Chengdu-Chongqing) branch of Southwestern Mandarin spoken in Chongqing municipality and eastern Sichuan (ISO 639-3: cmn as Mandarin Chinese; no separate code; Glottolog: sich1238 Sichuanese). All 30 seeds are real administrative divisions (districts/counties) of Chongqing Municipality: Yuzhong, Jiangbei, Shapingba, Jiulongpo, Nan'an, Beibei, Yubei, Banan, Dadukou (core urban districts) and Qianjiang, Fuling, Wanzhou, Hechuan, Tongliang, Changshou, Jiangjin, Yongchuan, Nanchuan, Qijiang, Dazu, Bishan, Tongnan, Rongchang, Kaizhou, Liangping, Wulong, Pengshui, Xiushan, Youyang, Shizhu (outer districts/autonomous counties). Per Wikipedia, Chongqing dialect is spoken in all districts of Chongqing City. District/county names function as their seat-town settlement names. No duplicates, no non-place tokens."
