      "verified_at": "2026-10-20T08:07:35.977Z",
      "notes": "Cilician Arabic (Glottolog cili1234; Cilicia-Antioch Arabic) is a Levantine Arabic dialect spoken in the Cilicia region of southern Turkey (Hatay, Mersin, Adana provinces). ISO 639-3: covered by apc (North Levantine Arabic, now merged into Levantine Arabic). Brill EALO confirms Arabic dialects of Cilicia spoken in Adana, Tarsus, and Mersin. All 25 seeds are real towns/districts in Hatay (Antakya, Iskenderun, Samandag/Samandag, Dortyol/Dortyol, Kirikhan/Kirikhani, Defne, Altinozu/Altinozu), Adana (Adana, Tarsus, Karatas/Karatas, Kucuk Karatas, Yuregir/Yuregir, Seyhan), Mersin (Mersin, Kazanli/Kazanli), and Osmaniye (Bahce). Remaining seeds are village/mahalle-level toponyms in the same region (Il-Gilli, Tekebasi, Dursunlu, Karacailyas, Karayusuflu, Kokluce, Cagimlar, Akkapi, Karahan). No duplicates, no self-references, no non-place tokens."
