      "notes": "Khe (ISO 639-3: kqg; Glottolog khee1238) is a Khmeric language spoken in Siem Pang District, Stung Treng Province, Cambodia (Sesan/Srepok/Sekong river valleys). The seed list is invalid: most entries are Cambodian PROVINCES, not settlements (Kratie, Mondulkiri, Ratanakiri, Preah Vihear, Kampong Thom, Kampong Cham, Battambang, Pursat, Kampong Speu, Takeo, Svay Rieng, Kandal, Oddar Meanchey); several seeds are in Vietnam (BinhPhuoc, TayNinh, DamHa, TrangBom, SonHoa), Thailand (Phayao), or Laos (ViengPhoukha), outside the Khe area; Phnom Penh and Siem Reap are major cities not in Stung Treng. No seed lies in the documented Khe area (Stung Treng/Siem Pang). Fewer than 25 valid seeds remain (0 kept). Entry cannot be verified."
