      "notes": "Language: Yakkha (Yakha), ISO 639-3 ybh, Glottocode yakk1236. Documented area: southern Sankhuwasabha district and northern Dhankuta district, Nepal, east of the Arun River (Wikipedia Yakkha language/people). Verified 27 of 33 seeds as real Yakkha villages/traditional areas from Wikipedia Yakkha people article (Panch-Khapan: Sibhuwa/Syabun/Wana/Dadagau/Swachi/Yangsijong/Wabun/Maidane/Chitlang; Dash-Majhiya: Madi Mulkharka/Tamafok/Tellok/Mamgling/Ankhibhuin/Hombong/Chanuwa/Dandagaun; Panch-Majhiya: Marrek/Kingring/Chapabhuin/Aambote/Chainpur) plus Pakhribas, Phalate, Marek Katahare, Arkhaule Jitpur (VDCs), Chainpur (town). Removed 6 seeds that are NOT settlements: Sankhuwasabha (district name, not a settlement), Dhankuta (district name), Arun River (river), Mugakhola (khola=river), Sinuwakhola (khola=river), Mugali (dialect/variety name, not a settlement - actual village is Muga). 27 seeds kept (>=25 floor met)."
