      "verified_at": "2026-10-20T08:07:35.977Z",
      "notes": "Be-Jizhao combines Be/Ong Be (ISO 639-3: onb; Glottolog ling1270, north-central Hainan) and Jizhao (Glottolog jizh1234, Jizhao Village, Tanba Town, Wuchuan, Guangdong). The Be languages article confirms settlements: Lingao County (Lincheng, Xinying), Bailian (Chengmai County), Longtang Township (Qiongshan District), Qiaotou, Huangtong, Maniao, Jialai, Meiliang, Longqiao, Longquan, Yongxing, Shishan, Changliu, Laocheng, Bohou. The Jizhao article confirms Jizhao village, Tanba Town, Wuchuan, and hamlets Jizhao/Meilou/Hong. Lingao County article confirms Limko is the former romanization of Lingao. All 25 seeds are real settlements in the Be (Hainan) and Jizhao (Wuchuan, Guangdong) areas. Note: Lingao and Limko are alternate romanizations of Lingao County (same place); both are authentic place names and neither is an invented token. No duplicates by exact string, no self-references, no non-place tokens."
