      "notes": "Tamang (ISO 639-3 taj/tdg/tge, Glottolog nucl1729, Ethnologue taj) is a Tibeto-Burman language of central Nepal; Rasuwa District is ~69% Tamang and its former VDCs (per Wikipedia Rasuwa District) include Bhorle, Briddhim, Chilime, Gatlang, Goljung, Haku, Laharepauwa, Langtang, Ramche, Syaphru, Thuman, Timure. Academic survey (Kvicalova, Slade & Gawne 2017, PMC4227083) documents Langtang-region Tamang villages: Langtang, Mundu, Kyanjin Gompa, Thuman, Timure, Bridhim, Thulo Syabru. Tamang Heritage Trail sources confirm Syabrubesi, Gatlang, Tatopani, Nagthali, Thuman, Briddim, Dhunche, Rasuwagadhi. Kept 25 real Tamang-area settlements (Rasuwa/Nuwakot): Syabrubesi, Gatlang, Goljung, Chilime, Tatopani, Nagthali, Thuman, Briddim, Timure, Rasuwagadhi, Laharepauwa, Dhunche, Bidur, Trishuli, Kakani, Kispang, Taruka, Thaprek, Haku, Ramche, Bhorle, Langtang, Kyanjin, Mundu, Thulo Syafru. Removed 8 seeds not confirmed as Tamang-area settlements: Chyamthang, Golung, Ghattekhola, Bethan, Bhadratar, Samundratar, Urleni, Parbati (Parbati Kunda is a lake). 25 kept >= 25 floor."
