      "notes": "Language confirmed: Tày, ISO 639-3 tyz, Glottolog tayy1238, per Wikipedia citing Ethnologue 19th ed. (2016) and General Statistics Office of Vietnam 2019 census. Documented area: northeastern Vietnam (Cao Bằng, Lạng Sơn, Hà Giang, Thái Nguyên, Tuyên Quang, Bắc Kạn provinces), where Tày is a major minority language (Tày 40.84% Cao Bằng, 36.08% Lạng Sơn, 22.55% Hà Giang, 11.69% Thái Nguyên, 26.20% Tuyên Quang, 52.58% Bắc Kạn). 27 of 31 seeds confirmed as real districts in Tày-speaking provinces from census-cited provincial administrative divisions: Lạng Sơn (Trang Dinh/Tràng Định, Van Quan/Văn Quan, Chi Lang/Chi Lăng, Cao Loc/Cao Lộc, Binh Gia/Bình Gia, Loc Binh/Lộc Bình, Dinh Lap/Đình Lập); Hà Giang (Dong Van/Đồng Văn, Meo Vac/Mèo Vạc, Yen Minh/Yên Minh, Hoang Su Phi/Hoàng Su Phì, Xin Man/Xín Mần, Quang Binh/Quảng Bình, Vi Xuyen/Vị Xuyên); Cao Bằng (Trung Khanh/Trùng Khánh, Thach An/Thạch An, Ha Lang/Hạ Lang); Thái Nguyên (Dai Tu/Đại Từ, Phu Luong/Phú Lương, Vo Nhai/Võ Nhai); Tuyên Quang (Na Hang, Lam Binh/Lâm Bình, Yen Son/Yên Sơn, Son Duong/Sơn Dương, Chiem Hoa/Chiêm Hoá); Bắc Kạn (Cho Don/Chợ Đồn, Na Ri/Na Rì). 4 seeds removed as peripheral/provincial names not confirmed as core Tày settlements: Bac Giang, Yen Bai, Phu Tho, Hanoi (Hanoi is the Kinh-majority capital, not a Tày settlement). 27 seeds retained (≥25 floor met)."
