      "notes": "Sarikoli (ISO 639-3 srh, Glottolog sari1246) is spoken in Tashkurgan Tajik Autonomous County (Pamirs, Kashgar Prefecture, Xinjiang) and Chitral/Broghil, Pakistan. Primary sources (Wikipedia, Glottolog, Ethnologue) confirm the Sarikoli area is Tashkurgan County. Of the 31 seeds, only Tashkurgan is an authentic Sarikoli settlement. Taxkorgan is a duplicate of Tashkurgan (official English spelling is Taxkorgan). The other 29 seeds are Xinjiang-wide cities (Kashgar, Yarkand, Hotan, Aksu, Korla, Kuqa, Alar, Tumxuk, Wujiaqu, Beitun, Shihezi, Changji, Urumqi, Ili, Karamay, Altay, Tacheng, Bole, Alashankou, Horgos, Jinghe, Manas, Hutubi, Fukang, Qitai, Jimsar) and Ningxia cities (Qingtongxia, Wuzhong, Yinchuan) far outside the Sarikoli-speaking Pamir area. Only 1 authentic seed remains (< 25), so the entry cannot be verified."
