      "notes": "Bijiang Bai is a Northern Bai dialect spoken in the Lushui (formerly Bijiang County) area of Nujiang Prefecture, Yunnan, China (Wang 2006; Allen 2007). Many seeds are outside the Bijiang Bai area: Dali, Lijiang, Jianchuan, Heqing, Eryuan, Binchuan, Weishan, Yunlong, Xiangyun, Shuanglang are in Dali Prefecture (Southern/Central Bai area); Fengqing, Yongping, Longling, Changning are in Baoshan Prefecture; Zhongdian/Shangri-La, Deqin are in Diqing Prefecture. Several seeds are Bai dialect names, not settlements: Tuoluo, Gongxing, Enqi, Jinman, Ega (Wang 2012 documents these as dialect sites in Lanping/Lushui/Weixi counties, not settlement names). Only Bijiang/Lushui, Liuku, Pianma, Gongshan, Fugong, Weixi, Lanping, Nujiang are in the documented Bijiang Bai area - 9 seeds remain, below the 25-seed floor."
