      "verified_by": "namebase-verifier",
      "verified_at": "2026-10-20T08:07:35.978Z",
      "notes": "Ravula (ISO 639-3 yea, Glottolog ravu1237) is a Dravidian language spoken in Kodagu (Coorg) district, Karnataka and Wayanad/Kannur districts, Kerala, India; concentrated in Virajpet taluk with populations in Heggadadevanakote, Piriyapatna, Hunsur (Mysore) and Mananthavady/Tirunelly (Wayanad) (Wikipedia, Ethnologue, Glottolog). One seed removed: Badaga is the Badaga language/people of the Nilgiris (Tamil Nadu), not a Kodagu/Ravula settlement — a language-name-as-seed defect. All other 30 seeds are real settlements in Kodagu/Wayanad/Mysore within the documented Ravula area (Virajpet, Somvarpet, Madikeri, Gonikoppal, Kushalnagara, Siddapura, Ponnampet, Ammathi, Tithimathi, Nokya, Hebbale, Balele, Kutta, Arakeri/Arekeri, Devanoor/Devanur, Kurchi, Tirunelly, Kartikulam, Bavali, Heggadadevanakote, Piriyapatna, Hunsur, Kothur, Kanoor, Nalkeri, Santapura, Kakuru, Chikkiri, Badagarakeri, Devarakadu). No duplicates, no self-references after removal."
