      "notes": "Sadri (Nagpuri), ISO 639-3 sck, Glottolog sadr1248. Documented area per Glottolog/Wikipedia/Brill: Jharkhand, Chhattisgarh, Odisha (west/central Chota Nagpur), with Sadri also spoken in Nepal tea-garden areas. Kept seeds are real settlements in that area (Jharkhand: Chatra, Latehar, Daltonganj/Medininagar [same city, two names], Simdega, Gumla, Khunti, Bokaro, Hazaribagh, Ramgarh, Dhanbad, Giridih, Jamshedpur, Chaibasa; Chhattisgarh: Sarangarh, Ambikapur, Raigarh, Jashpur Nagar, Dharamjaigarh, Surajpur, Balrampur; Odisha: Sundargarh, Jharsuguda, Balangir) plus Dhaijan and Damak (confirmed Jhapa, Nepal settlements). Removed: Madhurgaon, Anarmani, Bahundangi, Shantinagar (could not be confirmed as real settlements against primary sources); Jhapa (a district/region, not a settlement name). 26 seeds kept >= 25 floor."
