      "verified_at": "2026-10-20T08:07:35.978Z",
      "notes": "Andaman Creole Hindi (Andaman Hindi) ISO 639-3: hca, Glottolog: anda1280. A Hindi-Bengali-Tamil-based creole trade language of the Andaman and Nicobar Islands, India, spoken especially in Port Blair and villages to the south (Singh 1994; Abbi 2021; Ethnologue). Territory districts: North and Middle Andaman (Diglipur, Mayabunder, Rangat), South Andaman (Port Blair, Ferrargunj), Nicobar (Car Nicobar, Nancowry, Great Nicobar) - confirmed via Andaman and Nicobar Islands Wikipedia. All 34 seeds are real settlements in the Andaman and Nicobar Islands: Port Blair, Diglipur, Rangat, Mayabunder, Baratang, Havelock/Swaraj Dweep, Neil Island, Car Nicobar, Nancowry, Camorta, Teressa, Katchal, Campbell Bay, Little Nicobar are major towns/islands; Ferrargunj, Wandoor, Wimberleyganj, Landfall Island are real settlements; Port McNeil is a historical name; Afra Bay, Malacca, Sawi, Kinyuka, Tamaloo, Chuckchucha, Arong, Perka, Big Lapati, Small Lapati, Tapoiming, Kimois, Teetop, Kinmai are Nicobarese village names. No duplicates, no self-references, no synthetic seeds."
