      "notes": "'Tai' (ISO 639-3: taw, Glottolog: taii1241) is the Tai language family (Kra-Dai), distributed across Southern China, Southeast Asia, and Northeast India — not a single language with a specific settlement area. First seed 'Tai' is a self-reference (language name used as its own seed) — invalid per guardrails. The 27 remaining seeds span China (Fangchenggang, Shantou, Wuzhou), Vietnam (Da Lat, Nha Trang, Rach Gia, Hanoi, Vinh, Da Nang, Can Tho, Phan Thiet, Hai Phong), Laos (Luang Prabang, Pakse, Sam Neua, Xieng Khouang, Sihanoukville is Cambodia actually, Vientiane, Phongsali), Cambodia (Sihanoukville, Pursat, Siem Reap, Takeo, Kampong Cham), Myanmar (Bago, Yangon), Thailand (Chiang Rai, Chieng Mai). No single language area can be confirmed for all seeds. Removing all 28 seeds leaves 0 < 25."
