      "notes": "Adeni Arabic = Ta'izzi-Adeni Arabic, ISO 639-3 acq, Glottolog taiz1242. Documented area per Glottolog/Wikipedia: Taiz and Aden governorates (Ta'izzi in Ta'izz + neighbouring Ibb; Adeni in Aden and immediate outlying rural areas). Kept seeds are real settlements in that southern-Yemen area (Aden city districts: Crater, Tawahi, Mualla, Al Mansura, Sheikh Othman, Dar Sad, Khur Maksar, Al Buraiqa; Taiz: Mocha/Al Mukha [same city, two names], Mawza, Maqbanah, Hayfan, Al Mawasit, Shara'b Ar Rawnah; Ibb: Jibla, Dhi as-Sufal, Yarim; Abyan/Lahij: Zinjibar, Mudiyah, Lahij, Mukayras; plus Dimnat Chadir and At Tawilah). Removed: Hais (Hodeidah governorate, Tihami area), Wadi Dawan (Hadhramaut, far east), Dammaj (Saada, far north), Kawkaban (Amman/Amran, far north) — all outside the Ta'izzi-Adeni documented area. 27 seeds kept >= 25 floor."
